/**
 * README.md generator — produces 100% auto-generated documentation
 * from source code (JSDoc + ts-morph) and registry metadata.
 *
 * No hand-written content. Everything comes from:
 * - Module-level JSDoc in src/index.ts (description, @example, @remarks)
 * - Export-level JSDoc + type signatures (via ts-morph)
 * - registry.json metadata (type, category, stack, secrets, etc.)
 * - package.json (dependencies, peerDependencies)
 *
 * @module
 */

import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { join } from 'node:path'

import type { ExtractedExport, ExtractedModule } from './api-extractor.js'
import { loadAppFrameworks } from './registry.js'
import type { MoleculeSecret, RegistryEntry } from './schema.js'

// ============================================================================
// Types
// ============================================================================

export interface PackageJson {
  name: string
  version: string
  description?: string
  dependencies?: Record<string, string>
  peerDependencies?: Record<string, string>
  devDependencies?: Record<string, string>
}

export interface GeneratorOptions {
  /** For core packages: list of provider registry entries that implement this core interface */
  providers?: Array<{ name: string; entry: RegistryEntry }>
  /** Companion locale package name, if one exists */
  companionLocale?: string
  /** Absolute path to the molecule monorepo root */
  moleculeDir: string
  /** For provider packages: the core interface package's registry entry (to derive setter names) */
  coreInterfaceEntry?: RegistryEntry
  /** For provider packages: the core interface package name */
  coreInterfaceName?: string
  /**
   * For provider packages: the core interface package's module-level @e2e text.
   * Providers inherit the category's E2E guidance when they don't author their
   * own — the user-visible behavior to verify is provider-agnostic.
   */
  coreE2e?: string
  /** The bond infrastructure package name (e.g. @molecule/api-bond or @molecule/app-bond) */
  bondPkg?: string
  /**
   * Set of all known registry package names. Lets locale docs resolve the REAL
   * feature they translate when the bare concept name has no package of its own
   * (e.g. @molecule/app-locales-oauth-buttons → @molecule/app-oauth-buttons-react).
   */
  knownPackages?: ReadonlySet<string>
}

// ============================================================================
// Main entry point
// ============================================================================

/**
 * Generate a complete README.md from extracted API + registry metadata.
 * The entire file is generated — no hand-written content.
 *
 * @param extracted - Extracted API information from ts-morph
 * @param registryEntry - Registry metadata for this package
 * @param packageJson - The package's package.json contents
 * @param options - Additional context for generation
 * @returns The complete README.md content as a string
 */
/**
 * Machine-readable marker + human warning, prepended to every generated README.
 *
 * The file is `README.md` because that is what npm renders, what GitHub shows,
 * and what a coding agent looks for in `node_modules` without being taught
 * anything about molecule. The cost of using the conventional name is that
 * README is conventionally HAND-written — so the fact that this one is generated
 * has to be stated loudly, or someone edits it and their work is silently
 * overwritten on the next commit.
 */
const GENERATED_COMMENT_PREFIX = `<!--
AUTO-GENERATED — DO NOT EDIT THIS FILE.
Generated by \`mlcl sync-docs\` from the package's src/index.ts JSDoc + mlcl/registry.json.
Edits here are overwritten on the next commit (molecule's pre-commit hook regenerates).
To change this document, edit the module-level JSDoc in src/index.ts.`

/**
 * Marker line carrying the generation timestamp.
 *
 * A timestamp makes generator output non-deterministic, which would wreck the
 * pipeline: `sync-docs --check` compares generated bytes against the committed
 * file, so every run would report all ~900 docs as stale, and the pre-commit hook
 * would rewrite and re-stage the whole fleet on EVERY commit.
 *
 * So the timestamp is confined to ONE line with a fixed prefix, and every
 * comparison strips it via `stripGeneratedTimestamp()`. The file is rewritten
 * only when the real content changes — at which point the stamp updates too.
 * That makes it mean "when this document last CHANGED", which is the useful
 * reading anyway; "when the generator last ran" would be noise.
 */
export const GENERATED_AT_PREFIX = 'Generated: '

/**
 * Remove the generation-timestamp line so two documents can be compared for
 * MEANINGFUL difference.
 *
 * @param md - Document contents.
 * @returns The contents with the timestamp line removed.
 */
export function stripGeneratedTimestamp(md: string): string {
  return md
    .split('\n')
    .filter((line) => !line.startsWith(GENERATED_AT_PREFIX))
    .join('\n')
}

/**
 * Rendered note explaining what this document is. It renders AFTER the module
 * description — never between the title and it — because the description is the
 * package's own summary and the note is the generator's boilerplate: every
 * truncation of a README (the `read_molecule_doc` cap, and the context fitter's
 * digest of an older read) keeps the TOP of the document, so boilerplate above
 * the description spends the whole budget on "this file is generated" and
 * carries none of what the package documents. X0 flash-m98 (2026-10-17) lost ten
 * minutes to exactly that: the 600-character digest of `@molecule/api-resource-user`
 * was the banner comment, the title and this note, while the paragraph that
 * explained its bug sat at character 1,157.
 */
const GENERATED_NOTE = `> **Auto-generated, AI-first package reference** for the [molecule.dev](https://molecule.dev) ecosystem.
> It is written to be read by coding agents as much as by people, and is generated from this
> package's source — edit \`src/index.ts\` JSDoc, not this file.`

/**
 * Prepend the generated-file banner. The reader-facing note ({@link GENERATED_NOTE})
 * is a section the body generators place, after the description.
 *
 * @param md - The generated document body, whose first line is the `# title`.
 * @returns The document with the banner applied.
 */
function withGeneratedBanner(md: string): string {
  const banner = `${GENERATED_COMMENT_PREFIX}\n${GENERATED_AT_PREFIX}${new Date().toISOString()}\n-->`
  return `${banner}\n\n${md}`
}

export function generateMoleculeMd(
  extracted: ExtractedModule,
  registryEntry: RegistryEntry,
  packageJson: PackageJson,
  options: GeneratorOptions,
): string {
  const body =
    registryEntry.type === 'locales'
      ? generateLocaleMd(extracted, registryEntry, packageJson, options)
      : generateStandardMd(extracted, registryEntry, packageJson, options)

  return withGeneratedBanner(body)
}

// ============================================================================
// Standard package generation
// ============================================================================

function generateStandardMd(
  extracted: ExtractedModule,
  entry: RegistryEntry,
  pkg: PackageJson,
  options: GeneratorOptions,
): string {
  const sections: string[] = []

  // 1. Title
  sections.push(`# ${pkg.name}`)

  // 2. Description — the package's own summary, and the first text after the
  // title. It is the one part of a README every truncation keeps (see
  // GENERATED_NOTE), so nothing the generator writes may precede it.
  const description = extracted.description || entry.description
  if (description) {
    sections.push(description)
  }

  // 2b. What this document is — the generator's boilerplate, after the summary.
  sections.push(GENERATED_NOTE)

  // 3. Quick Start (from module-level @example) — promoted above metadata
  // and API so the FIRST code block a reader / weaker AI model sees is
  // the canonical usage example, not the `npm install` line.
  if (extracted.examples && extracted.examples.length > 0) {
    sections.push(generateUsageSection(extracted.examples))
  }

  // 4. Type / Category / Stack metadata
  sections.push(generateMetadataSection(entry))

  // 5. Installation
  sections.push(generateInstallSection(pkg, entry))

  // 6. API (from exports)
  if (extracted.exports.length > 0) {
    sections.push(generateApiSection(extracted.exports, pkg.name))
  }

  // 7. Available Providers — ANY package with registered providers lists them,
  // not just type 'core': feature/middleware/native abstractions (app-charts,
  // app-clipboard, api-middleware-*) have provider bonds implementing them too,
  // and their docs must name the choices the same way cores do.
  if (options.providers && options.providers.length > 0) {
    sections.push(generateProvidersSection(options.providers))
  }

  // 8. Core Interface (for provider packages)
  if (entry.type === 'provider' && entry.implements) {
    sections.push(generateCoreInterfaceSection(entry.implements))
  }

  // 8b. Bond Wiring (for provider packages — shows how to wire this provider)
  const bondWiring = generateBondWiringSection(entry, pkg, options, extracted.examples ?? [])
  if (bondWiring) {
    sections.push(bondWiring)
  }

  // 8c. Services (for resource packages that export services)
  const servicesSection = generateServicesSection(entry, pkg, options)
  if (servicesSection) {
    sections.push(servicesSection)
  }

  // 9. Injection Notes — auto-derived from peerDependencies + secrets + @remarks
  const injectionNotes = generateInjectionNotes(pkg, entry, extracted.remarks)
  if (injectionNotes) {
    sections.push(injectionNotes)
  }

  // 9b. E2E Tests — module-level @e2e; providers without their own inherit
  // the core interface's text (the behavior to verify is provider-agnostic)
  const e2e = extracted.e2e ?? options.coreE2e
  if (e2e) {
    sections.push(`## E2E Tests\n\n${e2e}`)
  }

  // 10. Translations (if companion locale exists)
  if (options.companionLocale) {
    sections.push(generateTranslationsSection(options.companionLocale))
  }

  return sections.join('\n\n') + '\n'
}

// ============================================================================
// Locale package generation
// ============================================================================

function generateLocaleMd(
  extracted: ExtractedModule,
  entry: RegistryEntry,
  pkg: PackageJson,
  options: GeneratorOptions,
): string {
  const sections: string[] = []
  const pkgDir = join(options.moleculeDir, entry.path)
  const srcDir = join(pkgDir, 'src')

  // 1. Title
  sections.push(`# ${pkg.name}`)

  // 2. Description — first text after the title; the note goes after it (see
  // the standard generator for why).
  const description = extracted.description || entry.description
  if (description) {
    sections.push(description)
  }

  // 2b. What this document is.
  sections.push(GENERATED_NOTE)

  // 3. Purpose — determine which package this translates
  const translatesPackage = inferTranslatedPackage(pkg.name, options.knownPackages)
  const langFiles = getLangFiles(srcDir)
  const translationKeys = getTranslationKeys(srcDir)
  const keyCount = Object.keys(translationKeys).length

  if (translatesPackage) {
    sections.push(
      `## Purpose\n\nProvides translations for the \`${translatesPackage}\` package` +
        (keyCount > 0
          ? ` which has ${keyCount} translation key${keyCount !== 1 ? 's' : ''}.`
          : '.'),
    )
  }

  // 4. Languages
  if (langFiles.length > 0) {
    const sorted = [...langFiles].sort((a, b) => a.localeCompare(b))
    sections.push(
      `## Languages\n\n${langFiles.length} language${langFiles.length !== 1 ? 's' : ''} supported: ${sorted.join(', ')}.`,
    )
  }

  // 5. Usage
  const typeExports = extracted.exports.filter((e) => e.kind === 'type' || e.kind === 'interface')
  const langExportSample = langFiles.slice(0, 3).join(', ')
  const typeExportSample = typeExports.map((e) => e.name).join(', ')

  if (langExportSample || typeExportSample) {
    let usageCode = `import { ${langExportSample} } from '${pkg.name}'`
    if (typeExportSample) {
      usageCode += `\nimport type { ${typeExportSample} } from '${pkg.name}'`
    }
    sections.push(`## Quick Start\n\n\`\`\`typescript\n${usageCode}\n\`\`\``)
  }

  // 5b. Registration — how the bond's translations actually reach t(). Locale
  // bonds are pure data; without this section a weak executor either imports
  // locales and does nothing with them or hand-writes translations inline.
  const i18nPackage = entry.stack === 'api' ? '@molecule/api-i18n' : '@molecule/app-i18n'
  sections.push(
    `## Registration\n\n` +
      `In an mlcl-scaffolded app, installed locale bonds are registered automatically ` +
      `by the app's i18n setup at startup — installing this package is normally all ` +
      `you need. To register manually (or in a custom app), pass the whole module to ` +
      `\`registerLocaleModule\` from \`${i18nPackage}\` at startup:\n\n` +
      `\`\`\`typescript\nimport { registerLocaleModule } from '${i18nPackage}'\nimport * as locales from '${pkg.name}'\n\nregisterLocaleModule(locales)\n\`\`\``,
  )

  // 5c. Editing translations — the canonical-key-set + no-inline-translations rules.
  sections.push(
    `## Editing translations\n\n` +
      `\`en.ts\` is the canonical key set — every other language file mirrors its keys. ` +
      `To change or add strings, edit the locale files in this package (add new keys to ` +
      `\`en.ts\` first) or merge overrides at runtime with \`addTranslations(locale, map)\`. ` +
      `Never hand-write translations inline in feature code: features call ` +
      `\`t(key, values, { defaultValue })\` and THIS bond supplies the translations — ` +
      `inline strings bypass every other language.`,
  )

  // 6. Translation Keys table
  if (keyCount > 0) {
    const rows = Object.entries(translationKeys).map(([key, value]) => `| \`${key}\` | ${value} |`)
    sections.push(
      `## Translation Keys\n\n| Key | English |\n|-----|---------|` + '\n' + rows.join('\n'),
    )
  }

  // 7. Metadata
  const metaLines = [`- **Type:** ${entry.type}`, `- **Category:** ${entry.category}`]
  if (entry.stack) metaLines.push(`- **Stack:** ${entry.stack}`)
  if (translatesPackage) metaLines.push(`- **Translates:** \`${translatesPackage}\``)
  sections.push(`## Metadata\n\n${metaLines.join('\n')}`)

  return sections.join('\n\n') + '\n'
}

// ============================================================================
// Section generators
// ============================================================================

function generateMetadataSection(entry: RegistryEntry): string {
  return `## Type\n\`${entry.type}\``
}

function generateInstallSection(pkg: PackageJson, entry: RegistryEntry): string {
  const parts = [`npm install ${pkg.name}`]

  // Add runtime dependencies
  if (entry.runtimeDependencies && entry.runtimeDependencies.length > 0) {
    parts[0] += ' ' + entry.runtimeDependencies.join(' ')
  }

  // Add dev dependencies hint for runtime deps that need @types
  const devTypeDeps = entry.runtimeDependencies
    ?.filter((dep) => {
      // Check if @types/<dep> exists in package.json devDeps
      const typeDep = `@types/${dep}`
      return pkg.devDependencies?.[typeDep]
    })
    .map((dep) => `@types/${dep}`)

  if (devTypeDeps && devTypeDeps.length > 0) {
    parts.push(`npm install -D ${devTypeDeps.join(' ')}`)
  }

  return `## Installation\n\`\`\`bash\n${parts.join('\n')}\n\`\`\``
}

function generateUsageSection(examples: string[]): string {
  const blocks = examples.map((example) => {
    // If the example already has code fences, use as-is
    if (example.includes('```')) {
      return example
    }
    return `\`\`\`typescript\n${example}\n\`\`\``
  })

  return `## Quick Start\n\n${blocks.join('\n\n')}`
}

/**
 * Per-export prose cap. A README is the whole reference a reader gets — the
 * point is that every export carries its description, not that any one export
 * carries all of it. Past this, a block is cut at a line boundary and pointed
 * at the source, so the document stays scannable and no export is dropped.
 */
const MAX_EXPORT_DESCRIPTION_CHARS = 1500

/**
 * Per-export declaration cap. A re-export of an external library's types
 * (`export * from '@playwright/test'`) otherwise inlines a 270 KB interface —
 * one such block dwarfs the rest of the fleet's docs combined. Long blocks are
 * cut at a line boundary and pointed at the `.d.ts` that ships the full text.
 *
 * Set high enough that an ordinary interface or class — the ones a reader
 * actually needs whole — fits: across the fleet only ~20 of 1031 packages have
 * a single declaration longer than this.
 */
const MAX_DECLARATION_CHARS = 8000

/**
 * Where an export's untruncated text lives once the package is installed.
 *
 * The package's own `src/x.ts` compiles to `dist/x.d.ts`, which ships in the
 * tarball. A re-exported dependency's type did NOT compile into that dist —
 * it lives in the dependency's own files — so that case points at the
 * dependency instead of at a file the truncated text was never in.
 *
 * @param packageName - The package being documented (`@molecule/...`).
 * @param exp - The export whose block had to be cut.
 * @returns A path the reader can open from a project root.
 */
function installedDeclarationPath(packageName: string, exp: ExtractedExport): string {
  if (exp.sourceFile) {
    return `node_modules/${packageName}/dist/${exp.sourceFile.replace(/\.tsx?$/, '.d.ts')}`
  }
  if (exp.externalSource) return `node_modules/${exp.externalSource}`
  return `node_modules/${packageName}/dist`
}

/**
 * Cut text to a character budget at the last line boundary, so a truncated
 * block never ends mid-token.
 *
 * @param text - The text to bound.
 * @param limit - Maximum characters to keep.
 * @returns The kept text and whether anything was dropped.
 */
function capText(text: string, limit: number): { text: string; truncated: boolean } {
  if (text.length <= limit) return { text, truncated: false }
  const cut = text.slice(0, limit)
  const lastNewline = cut.lastIndexOf('\n')
  // Only honour a line boundary that keeps most of the budget — a single very
  // long line (a one-line type alias) still gets cut mid-line rather than
  // losing almost everything.
  const kept = lastNewline > limit * 0.5 ? cut.slice(0, lastNewline) : cut
  return { text: kept.trimEnd(), truncated: true }
}

/** A line that may open or close a code fence: a run of 3+ backticks or tildes. */
const CODE_FENCE_LINE = /^(`{3,}|~{3,})(.*)$/

/**
 * The delimiter that closes the code fence `text` ends inside, if any —
 * following CommonMark §4.5, where a closer is the SAME character as the
 * opener, at least as long, and carries no info string.
 *
 * A truncated description is cut at a line boundary, which can land mid-block:
 * the kept text then ends inside an open fence, and the "description
 * truncated" marker and the signature block after it are parsed as code.
 * Prettier repairs the document by widening the fence, which is how
 * `@molecule/app-auth`'s README got a ```ts fence that swallowed every heading
 * after it (xr-molecule-flash-m158).
 *
 * @param text - Markdown that may end inside a code block.
 * @returns The closing delimiter (` ``` `, ` ```` `, `~~~`), or `undefined`
 *   when every fence in the text is closed.
 */
function closingFenceFor(text: string): string | undefined {
  let open: { char: string; length: number } | undefined
  for (const line of text.split('\n')) {
    const m = CODE_FENCE_LINE.exec(line.trimStart())
    if (!m) continue
    if (!open) open = { char: m[1][0], length: m[1].length }
    else if (m[1][0] === open.char && m[1].length >= open.length && !m[2].trim()) open = undefined
  }
  return open ? open.char.repeat(open.length) : undefined
}

/** Capping context for one export block: heading level, package name, name prefix. */
interface ExportBlockContext {
  /** Markdown heading level — 4 for a top-level export, 5 for a namespace member. */
  level: number
  /** Package name, used to point a truncated declaration at the installed `.d.ts`. */
  packageName: string
  /** Dotted namespace prefix for a member (e.g. `authorization`); absent at top level. */
  prefix?: string
}

/**
 * Render one export as a single self-contained block: heading, description,
 * TypeScript signature, `@param` lines, `@returns` line.
 *
 * @param exp - The extracted export.
 * @param ctx - Heading level, package name, and namespace prefix.
 * @returns The markdown block.
 */
function formatExportBlock(exp: ExtractedExport, ctx: ExportBlockContext): string {
  switch (exp.kind) {
    case 'function':
      return formatFunctionExportDetailed(exp, ctx)
    case 'const':
      return formatConstantExport(exp, ctx)
    case 'namespace':
      return formatNamespaceExport(exp, ctx)
    default:
      return formatDeclarationExport(exp, ctx)
  }
}

/** The name to show in a heading: `ns.member` for a namespace member. */
function displayName(exp: ExtractedExport, ctx: ExportBlockContext): string {
  return ctx.prefix ? `${ctx.prefix}.${exp.name}` : exp.name
}

/**
 * The description paragraph for an export, bounded and — when cut — followed by
 * a pointer to the file that still has the whole text.
 */
function boundedDescription(exp: ExtractedExport, ctx: ExportBlockContext): string | undefined {
  if (!exp.description) return undefined
  const { text, truncated } = capText(exp.description, MAX_EXPORT_DESCRIPTION_CHARS)
  if (!truncated) return text
  // Close a fence the cut landed inside, so the marker and the signature block
  // that follows stay prose instead of being swallowed as code.
  const close = closingFenceFor(text)
  return `${text}${close ? `\n${close}` : ''}\n\n*(description truncated — read the full text in \`${installedDeclarationPath(ctx.packageName, exp)}\`.)*`
}

/** The signature code block for an export, bounded, with a pointer when cut. */
function declarationBlock(exp: ExtractedExport, ctx: ExportBlockContext): string | undefined {
  const source = exp.declaration ?? exp.signature
  if (!source) return undefined
  const { text, truncated } = capText(source, MAX_DECLARATION_CHARS)
  const body = truncated
    ? `${text}\n// … truncated — the full declaration is in ${installedDeclarationPath(ctx.packageName, exp)}`
    : text
  return `\`\`\`typescript\n${body}\n\`\`\``
}

/**
 * The `@param` and `@returns` lines for an export. `@param` entries describing
 * fields of a destructured object (`props.children`) stay listed here — they
 * belong to the single object param and are what the caller needs to fill in.
 */
function paramAndReturnLines(fn: ExtractedExport): string | undefined {
  const parts: string[] = []

  const describedParams = fn.params?.filter((p) => p.description)
  if (describedParams && describedParams.length > 0) {
    parts.push(describedParams.map((p) => `- \`${p.name}\` — ${p.description}`).join('\n'))
  }

  if (fn.returnDescription) {
    parts.push(`**Returns:** ${fn.returnDescription}`)
  }

  return parts.length > 0 ? parts.join('\n\n') : undefined
}

function generateApiSection(exports: ExtractedExport[], packageName: string): string {
  const sections: string[] = ['## API']
  const ctx: ExportBlockContext = { level: 4, packageName }

  // Group by kind — the order the reader looks for things in, and the order the
  // extractor already sorted each group into (source order within the kind).
  const groups: Array<{ title: string; kind: ExtractedExport['kind'] }> = [
    { title: '### Interfaces', kind: 'interface' },
    { title: '### Types', kind: 'type' },
    { title: '### Classes', kind: 'class' },
    { title: '### Enums', kind: 'enum' },
    { title: '### Functions', kind: 'function' },
    { title: '### Constants', kind: 'const' },
    { title: '### Namespaces', kind: 'namespace' },
  ]

  for (const group of groups) {
    const matching = exports.filter((e) => e.kind === group.kind)
    if (matching.length === 0) continue
    sections.push(group.title)
    for (const exp of matching) {
      sections.push(formatExportBlock(exp, ctx))
    }
  }

  return sections.join('\n\n')
}

/**
 * Format an interface, type alias, enum, or class export with full declaration code block.
 */
function formatDeclarationExport(exp: ExtractedExport, ctx: ExportBlockContext): string {
  const parts: string[] = []
  const deprecated = exp.deprecated ? ' *(deprecated)*' : ''

  parts.push(`${'#'.repeat(ctx.level)} \`${displayName(exp, ctx)}\`${deprecated}`)

  const description = boundedDescription(exp, ctx)
  if (description) {
    parts.push(description)
  }

  const declaration = declarationBlock(exp, ctx)
  if (declaration) {
    parts.push(declaration)
  }

  const paramsAndReturn = paramAndReturnLines(exp)
  if (paramsAndReturn) {
    parts.push(paramsAndReturn)
  }

  return parts.join('\n\n')
}

/**
 * Format a function export with signature code block, param descriptions, and return info.
 */
function formatFunctionExportDetailed(fn: ExtractedExport, ctx: ExportBlockContext): string {
  const parts: string[] = []
  const deprecated = fn.deprecated ? ' *(deprecated)*' : ''

  // Heading with compact param names. Destructured-member params (`props.children`,
  // `props.position` — from `@param root0.children` etc.) describe fields of the
  // single object param, so they belong in the param list below, NOT the signature.
  // Show only top-level params; collapse to `props` if the JSDoc listed only members.
  const topLevelParams = fn.params?.filter((p) => !p.name.includes('.')) ?? []
  let paramNames = topLevelParams.map((p) => `${p.name}${p.optional ? '?' : ''}`).join(', ')
  if (!paramNames && fn.params?.some((p) => p.name.includes('.'))) {
    paramNames = 'props'
  }
  parts.push(`${'#'.repeat(ctx.level)} \`${displayName(fn, ctx)}(${paramNames})\`${deprecated}`)

  const description = boundedDescription(fn, ctx)
  if (description) {
    parts.push(description)
  }

  // Full function signature in code block
  const declaration = declarationBlock(fn, ctx)
  if (declaration) {
    parts.push(declaration)
  }

  const paramsAndReturn = paramAndReturnLines(fn)
  if (paramsAndReturn) {
    parts.push(paramsAndReturn)
  }

  return parts.join('\n\n')
}

/**
 * Format a constant export with type declaration.
 */
function formatConstantExport(c: ExtractedExport, ctx: ExportBlockContext): string {
  const parts: string[] = []
  const deprecated = c.deprecated ? ' *(deprecated)*' : ''

  parts.push(`${'#'.repeat(ctx.level)} \`${displayName(c, ctx)}\`${deprecated}`)

  const description = boundedDescription(c, ctx)
  if (description) {
    parts.push(description)
  }

  const declaration = declarationBlock(c, ctx)
  if (declaration) {
    parts.push(declaration)
  }

  const paramsAndReturn = paramAndReturnLines(c)
  if (paramsAndReturn) {
    parts.push(paramsAndReturn)
  }

  return parts.join('\n\n')
}

/**
 * Format a namespace export — `export * as ns from './file'`.
 *
 * Each member gets its OWN block at the same depth as a top-level export, with
 * its signature, description, `@param` lines and `@returns` line, because the
 * namespace is the only place those members appear. A bare `name — kind: first
 * line` list reads as documentation while leaving the reader to grep the
 * `.d.ts` for anything actionable (what a function takes, what it returns).
 *
 * The one exception is a namespace that re-exports a THIRD-PARTY module
 * (`export { z }` of zod): its members are that library's API, several hundred
 * of them, and expanding them would push this package's own exports out of
 * sight. That one is summarized and pointed at the module.
 */
function formatNamespaceExport(ns: ExtractedExport, ctx: ExportBlockContext): string {
  const parts: string[] = []
  const deprecated = ns.deprecated ? ' *(deprecated)*' : ''

  parts.push(`${'#'.repeat(ctx.level)} \`${displayName(ns, ctx)}\`${deprecated}`)

  const description = boundedDescription(ns, ctx)
  if (description) {
    parts.push(description)
  }

  if (ns.externalModule) {
    parts.push(
      `Re-exports the \`${ns.externalModule}\` module — \`${displayName(ns, ctx)}.<name>\` is exactly ` +
        `\`${ns.externalModule}.<name>\`, documented by that package (installed at ` +
        `\`node_modules/${ns.externalModule}\`).`,
    )
    return parts.join('\n\n')
  }

  if (!ns.members || ns.members.length === 0) {
    // Nothing to expand — fall back to whatever declaration we have.
    const declaration = declarationBlock(ns, ctx)
    if (declaration) parts.push(declaration)
    return parts.join('\n\n')
  }

  const memberCtx: ExportBlockContext = {
    ...ctx,
    level: Math.min(ctx.level + 1, 6),
    prefix: displayName(ns, ctx),
  }
  parts.push(
    `Re-exported as a namespace — reach every member below through it (e.g. \`${displayName(ns, ctx)}.<name>\`).`,
  )
  for (const member of ns.members) {
    parts.push(formatExportBlock(member, memberCtx))
  }

  return parts.join('\n\n')
}

function generateProvidersSection(
  providers: Array<{ name: string; entry: RegistryEntry }>,
): string {
  const rows = providers.map((p) => `| ${p.entry.label} | \`${p.name}\` |`)

  return (
    `## Available Providers\n\n| Provider | Package |\n|----------|---------|` +
    '\n' +
    rows.join('\n')
  )
}

function generateCoreInterfaceSection(implementsPackage: string): string {
  return `## Core Interface\nImplements \`${implementsPackage}\` interface.`
}

/**
 * Auto-generate Injection Notes from verifiable sources:
 * - peerDependencies from package.json
 * - secrets from registry.json
 * - runtimeDependencies from registry.json
 * - Optional @remarks from module JSDoc (for developer-authored notes)
 */
function generateInjectionNotes(
  pkg: PackageJson,
  entry: RegistryEntry,
  remarks?: string,
): string | null {
  const subsections: string[] = []

  // Requirements — derived from peerDependencies
  const peers = pkg.peerDependencies
  if (peers && Object.keys(peers).length > 0) {
    const peerLines = Object.entries(peers).map(([dep, version]) => `- \`${dep}\` ${version}`)
    subsections.push(`### Requirements\n\nPeer dependencies:\n${peerLines.join('\n')}`)
  }

  // Environment Variables — derived from registry secrets, including the
  // enriched setup metadata (label, instructions, setupUrl, example,
  // generate/provisioned markers) so the AI executor reading README.md
  // knows what each credential is, where it comes from, and — critically —
  // which ones need NO manual setup at all.
  if (entry.secrets && entry.secrets.length > 0) {
    const secretLines = entry.secrets.map((s) => formatSecretDocEntry(s))
    subsections.push(`### Environment Variables\n\n${secretLines.join('\n')}`)
  }

  // Runtime Dependencies — derived from registry
  if (entry.runtimeDependencies && entry.runtimeDependencies.length > 0) {
    const depLines = entry.runtimeDependencies.map((d) => `- \`${d}\``)
    subsections.push(`### Runtime Dependencies\n\n${depLines.join('\n')}`)
  }

  // Additional notes from @remarks (developer-authored, for things that can't be auto-derived)
  if (remarks) {
    subsections.push(remarks)
  }

  if (subsections.length === 0) return null

  return `## Injection Notes\n\n${subsections.join('\n\n')}`
}

/**
 * Format one registry secret as a Markdown list entry for the
 * Environment Variables section.
 *
 * Layout (one bullet per secret, fixed-prefix sub-bullets — designed so a
 * weak executor can scan it without ambiguity):
 *
 * ```
 * - `NAME` *(required)* — Label — default: `value`
 *   - **Auto-generated at scaffold — no manual setup.**          (generate)
 *   - **Provisioned automatically in molecule.dev sandboxes** …  (provisioned)
 *   - Setup: <instructions>
 *   - Get it here: [setupUrl](setupUrl)
 *   - Example: `sk_test_...`
 * ```
 *
 * Auto-generated (`generate`-marked) secrets suppress the Setup / Get it
 * here / Example lines — there is nothing for the user or executor to do,
 * and any guidance would just invite a pointless credential hunt. The
 * output is a pure function of the registry entry, keeping generation
 * deterministic.
 */
function formatSecretDocEntry(secret: MoleculeSecret): string {
  const required = secret.required ? ' *(required)*' : ' *(optional)*'
  const label = secret.label ? ` — ${secret.label}` : ''
  const defaultVal = secret.default ? ` — default: \`${secret.default}\`` : ''
  const lines = [`- \`${secret.name}\`${required}${label}${defaultVal}`]

  if (secret.generate) {
    lines.push('  - **Auto-generated at scaffold — no manual setup.**')
    return lines.join('\n')
  }

  if (secret.provisioned) {
    lines.push(
      '  - **Provisioned automatically in molecule.dev sandboxes** — manual setup only needed outside the platform.',
    )
  }
  if (secret.instructions) {
    lines.push(`  - Setup: ${secret.instructions}`)
  }
  if (secret.setupUrl) {
    lines.push(`  - Get it here: [${secret.setupUrl}](${secret.setupUrl})`)
  }
  if (secret.example) {
    lines.push(`  - Example: \`${secret.example}\``)
  }

  return lines.join('\n')
}

function generateTranslationsSection(localePackage: string): string {
  return `## Translations\n\nTranslation strings are provided by \`${localePackage}\`.`
}

/**
 * Generate a Bond Wiring section for provider packages.
 * Shows the complete setup pattern so AI/humans know exactly how to wire this provider.
 *
 * @param entry - Registry metadata for this provider package.
 * @param _pkg - The provider package's package.json contents.
 * @param options - Generator context (core interface exports, bond package name, etc.).
 * @param moduleExamples - The module's own `@example` blocks (from `src/index.ts`), used
 *   verbatim when the generic `setProvider(provider)` template would be misleading.
 */
function generateBondWiringSection(
  entry: RegistryEntry,
  _pkg: PackageJson,
  options: GeneratorOptions,
  moduleExamples: string[] = [],
): string | null {
  if (entry.type !== 'provider' || !entry.implements) return null

  const coreExports = options.coreInterfaceEntry?.exports ?? []
  const coreName = options.coreInterfaceName ?? entry.implements
  const pkgExports = entry.exports ?? []
  const bondWiring = entry.bondWiring

  // Determine bond type: named (has bondWiring with type=named) or singleton
  if (bondWiring?.type === 'named') {
    return generateNamedBondWiring(entry, _pkg, bondWiring, options)
  }

  // Singleton bond: find the setter from the core interface exports
  const setters = coreExports.filter((e) => /^(set|register)[A-Z]/.test(e))
  if (setters.length === 0) return null

  // App-side bonds never read env internally — it's an architecture
  // invariant (Vite only embeds `import.meta.env` into the client bundle at
  // BUILD time; there is no `process.env` to read at runtime), not a
  // per-package quirk. So when an app-side provider has a REQUIRED secret
  // and also exports a configurable `createProvider(options)`, the bare
  // lazy `provider` export can never receive that secret: bonding it
  // directly (the generic `setProvider(provider)` template below) compiles,
  // runs, and can even log the provider's own "not configured" warning —
  // but that warning fires even when the secret IS set correctly in the
  // app's env, because the value was simply never threaded through
  // `createProvider()`. Teaching the generic template here would ship that
  // exact trap (this is how Bond Wiring used to directly contradict the
  // module's own Quick Start `@example`, which already reads env and calls
  // `createProvider(options)` correctly). Re-emit that verbatim example
  // instead of guessing at an options shape the registry doesn't describe.
  const cannotSelfConfigure =
    entry.stack === 'app' &&
    (entry.secrets ?? []).some((s) => s.required) &&
    pkgExports.includes('createProvider')
  if (cannotSelfConfigure) {
    const requiredSecretNames = (entry.secrets ?? [])
      .filter((s) => s.required)
      .map((s) => s.name)
      .join(', ')
    const lines: string[] = [
      `## Bond Wiring`,
      '',
      `This provider cannot self-configure: app-side bonds never read env internally ` +
        `(Vite only embeds \`import.meta.env\`, not \`process.env\`), so the bare \`provider\` ` +
        `export can never receive the required ${requiredSecretNames} secret. Bonding it ` +
        `directly (\`setProvider(provider)\`) silently ships a no-op even when the secret ` +
        `IS set correctly in your app's env — call \`createProvider(options)\` with the ` +
        `secret read from your app's env, then pass the result to \`setProvider()\`.`,
    ]
    if (moduleExamples.length > 0) {
      const block = moduleExamples[0].includes('```')
        ? moduleExamples[0]
        : `\`\`\`typescript\n${moduleExamples[0]}\n\`\`\``
      lines.push('', 'See Quick Start above for the exact wiring:', '', block)
    }
    return lines.join('\n')
  }

  // Find the best provider export to pass to the setter
  const providerExport =
    entry.providerExportName ??
    pkgExports.find((e) => e === 'provider') ??
    pkgExports.find((e) => /^(provider|client|instance)$/.test(e))

  if (!providerExport) return null

  // Build setup function name from package name
  const shortName = extractShortNameForDocs(entry)
  const pascal = toPascalCase(shortName)

  const lines: string[] = [
    `## Bond Wiring`,
    '',
    'Setup function to register this provider with the core interface:',
    '',
  ]

  if (setters.length === 1) {
    // Simple case: one setter, one provider
    lines.push('```typescript')
    lines.push(`import { ${setters[0]} } from '${coreName}'`)
    lines.push(`import { ${providerExport} } from '${_pkg.name}'`)
    lines.push('')
    lines.push(`export function setup${pascal}(): void {`)
    lines.push(`  ${setters[0]}(${providerExport})`)
    lines.push('}')
    lines.push('```')
  } else {
    // Multiple setters (e.g. database has setPool + setStore)
    // Find matching exports for each setter
    const pairs: Array<{ setter: string; provider: string }> = []

    // The PRIMARY setter registers the provider itself. The core's registry
    // `bondSetter` — the setter whose parameter is the provider interface,
    // scanned from source — decides this; without it, a core that grew a second
    // setter is resolved by order and the README documents a call that cannot
    // compile (app-http-axios rendered `setAuthGate(provider)` beside a core
    // whose bond setter is setClient). Then `setProvider`, then
    // `set<PascalCase(category)>` (logger → setLogger, cors → setCors).
    const declared = options.coreInterfaceEntry?.bondSetter
    const categoryPascal = toPascalCase(entry.category ?? '')
    const primary =
      (declared && setters.includes(declared) ? declared : undefined) ??
      setters.find((s) => s === 'setProvider') ??
      setters.find((s) => s === `set${categoryPascal}`)
    if (primary) {
      pairs.push({ setter: primary, provider: providerExport })
    }

    for (const setter of setters) {
      if (setter === primary) continue
      // Extract the concept from the setter name: setPool -> pool, setStore -> store
      const concept = setter.replace(/^(set|register)/, '')
      const conceptLower = concept.charAt(0).toLowerCase() + concept.slice(1)
      const matchingExport =
        pkgExports.find((e) => e === conceptLower) ??
        pkgExports.find((e) => e.toLowerCase() === conceptLower.toLowerCase())
      if (matchingExport) {
        pairs.push({ setter, provider: matchingExport })
      }
    }

    if (pairs.length === 0) {
      // Fallback: just show first setter with the provider export
      pairs.push({ setter: setters[0], provider: providerExport })
    }

    const importedSetters = [...new Set(pairs.map((p) => p.setter))]
    setters.length = 0
    setters.push(...importedSetters)

    const imports = [...new Set(pairs.map((p) => p.provider))]

    lines.push('```typescript')
    lines.push(`import { ${setters.join(', ')} } from '${coreName}'`)
    lines.push(`import { ${imports.join(', ')} } from '${_pkg.name}'`)
    lines.push('')
    lines.push(`export function setup${pascal}(): void {`)
    for (const pair of pairs) {
      lines.push(`  ${pair.setter}(${pair.provider})`)
    }
    lines.push('}')
    lines.push('```')
  }

  return lines.join('\n')
}

/**
 * Generate wiring section for named bonds (oauth, payments, etc.)
 */
function generateNamedBondWiring(
  entry: RegistryEntry,
  pkg: PackageJson,
  bondWiring: NonNullable<RegistryEntry['bondWiring']>,
  options: GeneratorOptions,
): string | null {
  const bondPkg = options.bondPkg
  if (!bondPkg) return null

  const providerExports = bondWiring.providerExports ?? []
  if (providerExports.length === 0) return null

  const shortName = extractShortNameForDocs(entry)
  const pascal = toPascalCase(shortName)
  const category = bondWiring.bondCategory

  // Imports: all providerExports from this package
  const imports = providerExports.length > 0 ? providerExports : ['provider']

  const lines: string[] = [
    `## Bond Wiring`,
    '',
    'Setup function to register this provider with the bond system:',
    '',
  ]
  lines.push('```typescript')
  lines.push(`import { bond } from '${bondPkg}'`)
  lines.push(`import { ${imports.join(', ')} } from '${pkg.name}'`)
  lines.push('')
  lines.push(`export function setup${pascal}(): void {`)

  if (bondWiring.nameExport) {
    // Named with explicit name export: bond('category', nameExport, { ...exports })
    lines.push(`  bond('${category}', ${bondWiring.nameExport}, { ${imports.join(', ')} })`)
  } else {
    // Named without name export: derive name from package, pass first import
    const lastSegment = pkg.name.split('-').pop() ?? pkg.name
    lines.push(`  bond('${category}', '${lastSegment}', ${imports[0]})`)
  }

  lines.push('}')
  lines.push('```')

  return lines.join('\n')
}

/**
 * Generate a Services section for resource packages that export services.
 */
function generateServicesSection(
  entry: RegistryEntry,
  pkg: PackageJson,
  options: GeneratorOptions,
): string | null {
  const services = entry.services
  if (!services || services.length === 0) return null

  const bondPkg = options.bondPkg
  if (!bondPkg) return null

  const serviceImports = services.map((s) => s.export)

  const lines: string[] = [
    `## Services`,
    '',
    'This package exports services that should be registered with the bond system:',
    '',
    '```typescript',
    `import { bond } from '${bondPkg}'`,
    `import { ${serviceImports.join(', ')} } from '${pkg.name}'`,
    '',
  ]

  for (const service of services) {
    lines.push(`bond('${service.bondCategory}', ${service.export})`)
  }

  lines.push('```')

  return lines.join('\n')
}

// ============================================================================
// Helpers
// ============================================================================

/**
 * Infer which package a locale package translates from the package name.
 * e.g. @molecule/api-locales-database -> @molecule/api-database
 * e.g. @molecule/app-locales-auth -> @molecule/app-auth
 */
function inferTranslatedPackage(
  localePackageName: string,
  knownPackages?: ReadonlySet<string>,
): string | null {
  const match = localePackageName.match(/^@molecule\/(api|app)-locales-(.+)$/)
  if (!match) return null
  const base = `@molecule/${match[1]}-${match[2]}`
  if (!knownPackages) return base
  if (knownPackages.has(base)) return base
  // Locale bonds are framework-agnostic, but the feature they translate often
  // carries a framework suffix (e.g. @molecule/app-locales-oauth-buttons
  // translates @molecule/app-oauth-buttons-react). When the bare concept name
  // has no package of its own, resolve to the real framework variant rather
  // than pointing the doc at a non-existent package.
  for (const tok of Object.keys(loadAppFrameworks())) {
    const variant = `${base}-${tok}`
    if (knownPackages.has(variant)) return variant
  }
  // No real package matches the inferred name. Emitting the guess would point
  // the doc's Purpose/Translates at a phantom package (e.g. app-locales-common
  // → the non-existent @molecule/app-common) — omit the section instead.
  return null
}

/**
 * Get language file names (without .ts) from src dir, excluding index/types/__tests__.
 */
function getLangFiles(srcDir: string): string[] {
  try {
    return readdirSync(srcDir)
      .filter(
        (f) =>
          f.endsWith('.ts') &&
          !f.endsWith('.d.ts') &&
          f !== 'index.ts' &&
          f !== 'types.ts' &&
          !f.startsWith('__'),
      )
      .map((f) => f.replace(/\.ts$/, ''))
  } catch (_error) {
    // Best-effort: srcDir may not exist for packages without a src/ directory.
    // Returning [] is always safe — callers treat an empty list as "no languages".
    return []
  }
}

/**
 * Parse translation keys from en.ts. Returns key -> English value.
 */
function getTranslationKeys(srcDir: string): Record<string, string> {
  const keys: Record<string, string> = {}
  const enPath = join(srcDir, 'en.ts')

  if (!existsSync(enPath)) return keys

  const content = readFileSync(enPath, 'utf-8')
  const pattern = /['"]([^'"]+)['"]:\s*\n?\s*['"]([^'"]+)['"],?/g
  for (const match of content.matchAll(pattern)) {
    keys[match[1]] = match[2]
  }

  return keys
}

/**
 * Extract short name from a registry entry's path for bond setup function naming.
 * e.g. packages/api/bonds/database/postgresql -> database-postgresql
 */
function extractShortNameForDocs(entry: RegistryEntry): string {
  // Use path: packages/api/bonds/database/postgresql -> database-postgresql
  const parts = entry.path.split('/')
  // Find the index after 'bonds' and join remaining parts
  const bondsIdx = parts.indexOf('bonds')
  if (bondsIdx >= 0 && bondsIdx + 1 < parts.length) {
    return parts.slice(bondsIdx + 1).join('-')
  }
  // Fallback: last two parts
  return parts.slice(-2).join('-')
}

/**
 * Convert a hyphenated name to PascalCase.
 * e.g. database-postgresql -> DatabasePostgresql
 */
function toPascalCase(name: string): string {
  return name.replace(/(^|-)(\w)/g, (_: string, __: string, c: string) => c.toUpperCase())
}
